  "budget": {
    "agents": 0,
    "skills": 0,
    "hooks": 6,
    "workflows": 0,
    "scripts": 0
  },
  "requires": {
    "paths": ["bin/lib/agent-roster.mjs"]
  },
  "wiring": {
    "settings": {
      "PreCompact": [
        {
          "hooks": [
            {
              "type": "command",
              "command": "node \"$CLAUDE_PROJECT_DIR/.claude/hooks/write-compact-handoff.mjs\"",
              "timeout": 30
            }
          ]
        }
      ],
      "SessionStart": [
        {
          "matcher": "compact|resume|startup",
          "hooks": [
