export function readTarballReadme(tgz) {
  const tar = gunzip(tgz);
  const entry =
    findEntry(tar, (n) => /^readme\.md$/i.test(n)) ??
    findEntry(tar, (n) => /^readme(\.[^/]+)?$/i.test(n));
  return entry === undefined
    ? undefined
